use pathland_core::{category, component_type, parameter, tree, value_type, Frame, Opcode};

/// A decoded node in the host's native-element description.
#[derive(Debug, Clone, PartialEq)]
pub struct HostNode {
    pub id: u32,
    pub component_type: u16,

