        let now = player
            .playbin
            .query_position::<gst::ClockTime>()
            .map(|t| t.nseconds() as f64 / 1_000_000_000.0)
            .unwrap_or(0.0);
        if should_seek(now, target) {
            let _ = player.playbin.seek_simple(
                gst::SeekFlags::FLUSH,
