        // apply are flushed before the idle pump takes over.
        pump_once(&renderer, &pump);
        flush_pending(&pump, &pending, &on_event);
        let root = renderer.borrow().root_widget();
        if let Some(root) = root {
            window.set_child(Some(&root));
